effect.shader:
const int MAXIMO_DE_OITAVAS = 7;

float hash2(vec2 c) {
    c += vec2(float(seed) * 13.7);
    return fract(sin(dot(c, vec2(127.1, 311.7))) * 43758.5453);
}

/** Ruído suave 2D (valor nos cantos + smoothstep nos dois eixos). */
float ruido2(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 s = f * f * (3.0 - 2.0 * f);
    float a = hash2(i);
    float b = hash2(i + vec2(1.0, 0.0));
    float c = hash2(i + vec2(0.0, 1.0));
    float d = hash2(i + vec2(1.0, 1.0));
    return mix(mix(a, b, s.x), mix(c, d, s.x), s.y);
}

/** FBM: soma de oitavas, amplitude cai pela metade, frequência dobra. */
float fbm(vec2 p, int oitavas) {
    float soma = 0.0;
    float amp = 0.5;
    float peso = 0.0;
    for (int i = 0; i < MAXIMO_DE_OITAVAS; i++) {
        if (i >= oitavas) break;
        soma += ruido2(p) * amp;
        peso += amp;
        p *= 2.0;
        amp *= 0.5;
    }
    return soma / max(peso, 1e-4);
}

/** Rampa de cor do fogo: do vermelho escuro à ponta branca. */
vec3 rampa(float x) {
    x = clamp(x, 0.0, 1.0);
    vec3 c;
    if (x < 0.25)      c = mix(vec3(0.0), vec3(0.6, 0.0, 0.0), x / 0.25);
    else if (x < 0.5)  c = mix(vec3(0.6, 0.0, 0.0), vec3(1.0, 0.3, 0.0), (x - 0.25) / 0.25);
    else if (x < 0.75) c = mix(vec3(1.0, 0.3, 0.0), vec3(1.0, 0.9, 0.2), (x - 0.5) / 0.25);
    else               c = mix(vec3(1.0, 0.9, 0.2), vec3(1.0), (x - 0.75) / 0.25);
    return c;
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    vec2 p = vec2(acScreenNorm.x * acAspect, acScreenNorm.y) * scale;
    // O ruído escorre pra cima no tempo — é o que vira "chama subindo".
    p.y -= acTime * speed;

    int oit = clamp(int(detail + 0.5), 1, MAXIMO_DE_OITAVAS);
    float n = fbm(p, oit);

    // Máscara vertical: 1 na base, 0 no topo; `height` escala.
    float mascara = smoothstep(0.0, max(height, 1e-4), 1.0 - acScreenNorm.y);

    // Combina o ruído com a máscara: o produto é a quantidade de fogo no pixel.
    float quanto = n * mascara;
    quanto = clamp(quanto * intensity * 1.6, 0.0, 1.5);

    vec3 corDoFogo = rampa(quanto);
    float alfaDoFogo = clamp(quanto, 0.0, 1.0);

    // Mistura por SCREEN (fogo é luz, não tinta por cima).
    vec3 cor = 1.0 - (1.0 - original.rgb) * (1.0 - corDoFogo);
    cor = mix(original.rgb, cor, alfaDoFogo);
    float alfa = max(original.a, alfaDoFogo);

    fragColor = vec4(cor, alfa);
}
